// Install the PhotoMem SDK:
// npm install photomem

import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ apiKey: 'pm_your_api_key' });

// Create a memory
const memory = await client.memories.create({
  userId: 'user_123',
  userName: 'John Doe',
  content: 'Prefers dark mode and concise responses. Works in software engineering.',
  tags: ['preference', 'settings']
});

console.log(`Memory created: ${memory.id}`);

import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ apiKey: 'pm_your_api_key' });

// List all memories with pagination
const memories = await client.memories.list({
  limit: 20,
  offset: 0
});

console.log(`Total memories: ${memories.pagination.total}`);
memories.memories.forEach(memory => {
  console.log(`- ${memory.id}: ${memory.content.substring(0, 50)}...`);
});

import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ apiKey: 'pm_your_api_key' });

// Get a specific memory by ID
const memory = await client.memories.get('mem_a1b2c3d4e5f6');

console.log(`Memory: ${memory.content}`);
console.log(`User: ${memory.userName}`);
console.log(`Tags: ${memory.tags.join(', ')}`);

import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ apiKey: 'pm_your_api_key' });

// Update memory content and tags
const memory = await client.memories.update('mem_a1b2c3d4e5f6', {
  content: 'Updated memory content with more details.',
  tags: ['updated', 'detailed']
});

console.log(`Memory updated: ${memory.id}`);
console.log(`New content: ${memory.content}`);

import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ apiKey: 'pm_your_api_key' });

// Delete a memory
const result = await client.memories.delete('mem_a1b2c3d4e5f6');

console.log(`Memory deleted: ${result.message}`);
console.log(`Deleted at: ${result.deletedAt}`);

import { PhotoMemClient } from 'photomem';

const client = new PhotoMemClient({ apiKey: 'pm_your_api_key' });

// Search memories semantically
const results = await client.memories.search({
  query: "What are the user's preferences for UI design?",
  limit: 10,
  minRelevance: 0.7
});

console.log(`Found ${results.totalResults} relevant memories:`);
results.results.forEach(result => {
  console.log(`- [${result.relevanceScore.toFixed(2)}] ${result.memory.content}`);
});

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// List all API keys for a project
const apiKeys = await client.apiKeys.list({
  orgId: 'org_abc123def456',
  projectId: 'proj_xyz789ghi012'
});

console.log(`Found ${apiKeys.apiKeys.length} API keys:`);
apiKeys.apiKeys.forEach(key => {
  console.log(`- ${key.name} (${key.keyPrefix}...) - Status: ${key.status}`);
});

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Create a new API key
const result = await client.apiKeys.create({
  orgId: 'org_abc123def456',
  projectId: 'proj_xyz789ghi012',
  name: 'Production API Key',
  permissions: ['read', 'write']
});

console.log(`API Key created: ${result.apiKey.name}`);
console.log(`Full key (save this!): ${result.apiKey.key}`);
console.log(`Warning: ${result.warning}`);

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Revoke an API key
const result = await client.apiKeys.revoke({
  orgId: 'org_abc123def456',
  projectId: 'proj_xyz789ghi012',
  keyId: 'key_a1b2c3d4e5f6'
});

console.log(`API key revoked: ${result.message}`);
console.log(`Revoked at: ${result.revokedAt}`);

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Rotate API key with 7-day grace period
const result = await client.apiKeys.rotate({
  orgId: 'org_abc123def456',
  projectId: 'proj_xyz789ghi012',
  keyId: 'key_a1b2c3d4e5f6',
  gracePeriodDays: 7
});

console.log(`New API key: ${result.newApiKey.key}`);
console.log(`Old key expires at: ${result.oldApiKey.expiresAt}`);
console.log(`Warning: ${result.warning}`);

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// List all organizations
const result = await client.organizations.list();

result.organizations.forEach(org => {
  console.log(`${org.name} (${org.plan}) - Your role: ${org.yourRole}`);
  console.log(`  Members: ${org.memberCount}`);
});

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Create a new organization
const org = await client.organizations.create({
  name: 'My Startup',
  settings: {
    allowGuestAccess: false,
    defaultMemoryRetention: 90
  }
});

console.log(`Organization created: ${org.id}`);
console.log(`Slug: ${org.slug}`);

