import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Get organization details
const org = await client.organizations.get('org_abc123def456');

console.log(`${org.name} (${org.plan})`);
console.log(`Members: ${org.memberCount}, Projects: ${org.projectCount}`);
console.log(`Your role: ${org.yourRole}`);

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Delete organization
const result = await client.organizations.delete('org_abc123def456');

console.log(`Organization deleted: ${result.message}`);
console.log(`Deleted at: ${result.deletedAt}`);

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// List organization members
const result = await client.organizations.getMembers('org_abc123def456');

console.log(`Total members: ${result.totalMembers}`);
result.members.forEach(member => {
  console.log(`- ${member.fullName} (${member.email}) - Role: ${member.role}`);
});

import { PhotoMemClient } from 'photomem';

// Initialize with user authentication token
const client = new PhotoMemClient({ authToken: 'your_clerk_token' });

// Invite a new member
const invitation = await client.organizations.inviteMember({
  orgId: 'org_abc123def456',
  email: 'newmember@example.com',
  role: 'member',
  message: 'Welcome to the team!'
});

console.log(`Invitation sent: ${invitation.invitationId}`);
console.log(`Expires at: ${invitation.expiresAt}`);
